// Generated by scripts/build.mjs from src/core/discourse. Do not edit.
(() => {
"use strict";

// ---- text.js
const M_text = (() => {
// Shared text tools for the discourse checks (project-docs/DISCOURSE.md): one normal form for a quote
// and a passage, so a modern paraphrase and a nineteenth-century translation meet on the same
// words. Pure functions; no data, no network.

// Older English the public-domain translations use, mapped to the words a post would use.
const ARCHAIC = new Map(Object.entries({
  thee: "you", thou: "you", thy: "your", thine: "your", thyself: "yourself", ye: "you",
  art: "are", hast: "have", hath: "has", doth: "does", dost: "do", shalt: "shall", wilt: "will",
  canst: "can", couldst: "could", wouldst: "would", shouldst: "should", mayst: "may", didst: "did",
  wast: "was", wert: "were", whence: "where", whither: "where", unto: "to", oft: "often", ere: "before",
}));

// Words that carry no meaning of their own for matching. Kept short on purpose: "not" and "never"
// stay, since they flip a quote.
const STOP = new Set(("a an and are as at be been but by can could did do does for from had has have he her his i if in into is it its " +
  "me my of on or our she so than that the their them then there these they this those to too us was we were what when which who whom why " +
  "will with would you your yourself yourselves himself herself itself ourselves themselves shall should may might must also just very " +
  "all any each every such only own same other some more most much many upon about over under again once here how out up down off").split(" "));

// Letters only, lower case, accents folded, apostrophes and hyphenated line breaks joined.
function fold(s) {
  return String(s || "").normalize("NFKD").replace(/[̀-ͯ]/g, "")
    .replace(/(\w)-\s*\n\s*(\w)/g, "$1$2").replace(/[‘’ʼ']/g, "").toLowerCase();
}

// A light suffix strip, enough to meet "imagining" and "imagine", "thoughts" and "thought".
function stem(w) {
  if (w.length <= 4) return w;
  if (w.endsWith("ies") && w.length > 5) return w.slice(0, -3) + "y";
  if (w.endsWith("ing") && w.length > 6) return w.slice(0, -3);
  if (w.endsWith("ed") && w.length > 5) return w.slice(0, -2);
  if (w.endsWith("es") && w.length > 5) return w.slice(0, -2);
  if (w.endsWith("s") && !w.endsWith("ss")) return w.slice(0, -1);
  return w;
}

// Every word of a text in order, archaic forms modernised and stemmed.
function words(s) {
  return (fold(s).match(/[a-z0-9]+/g) || []).map((w) => stem(ARCHAIC.get(w) || w));
}

// The words that carry meaning, in order.
const content = (s) => words(s).filter((w) => !STOP.has(w) && w.length > 1);

// Levenshtein distance with an early stop once it passes max.
function editDistance(a, b, max = 3) {
  if (Math.abs(a.length - b.length) > max) return max + 1;
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    let best = i;
    for (let j = 1; j <= b.length; j++) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
      if (cur[j] < best) best = cur[j];
    }
    if (best > max) return max + 1;
    prev = cur;
  }
  return prev[b.length];
}

// True when word w appears in s with at most one letter wrong (OCR slips, a doubled letter in a
// handle). Words under six letters must match exactly.
function containsNear(s, w) {
  if (s.includes(w)) return true;
  if (w.length < 6) return false;
  for (let len = w.length - 1; len <= w.length + 1; len++) {
    for (let i = 0; i + len <= s.length; i++) if (editDistance(s.slice(i, i + len), w, 1) <= 1) return true;
  }
  return false;
}

// A short window of a passage around the first place one of the words occurs, cut at word edges.
function snippet(text, near, max = 280) {
  const t = String(text || "").replace(/\s+/g, " ").trim();
  if (t.length <= max) return t;
  const low = fold(t);
  const at = (near || []).map((w) => low.indexOf(w)).filter((i) => i >= 0).sort((a, b) => a - b)[0] ?? 0;
  const start = Math.max(0, at - Math.floor(max / 3));
  const cut = t.slice(start, start + max).replace(/^\S*\s/, start > 0 ? "" : "$&").replace(/\s\S*$/, "");
  return (start > 0 ? "… " : "") + cut + (start + max < t.length ? " …" : "");
}

return { STOP, fold, stem, words, content, editDistance, containsNear, snippet };
})();

// ---- quotes.js
const M_quotes = (() => {
// The quote finder (project-docs/DISCOURSE.md). It takes the quoted lines a post attributes to
// someone, looks for each in a bundled index of public-domain texts (src/ext/discourse/quotes.json),
// and checks a short list of sourced misattributions and of quotes attested outside the index.
// Every answer is one of: found, close paraphrase, listed as misattributed, attested elsewhere, or not
// found. "Not found" proves nothing: the index holds a few dozen works, not everything ever written.
const { content, fold, snippet, words } = M_text;

const QUOTE_DOES_NOT_PROVE = "A match shows these words, or close ones, in the passage cited. It does not show the person meant what the post says, and a translation is a translator's wording. Not finding a quote proves nothing: the index holds a few dozen public-domain works.";
const MIN_WORDS = 5, MAX_QUERIES = 8;

// Quoted spans in a post: text inside quotation marks, and the "Name: words" lines of a list.
// Returns { quotes: [{ text, by }], list: { lines, named, sourced } | null }.
function extractQuotes(post, names = []) {
  const text = String(post || "");
  const quotes = [];
  for (const m of text.matchAll(/["“«„]([^"“”«»„]{12,600})["”»“]/g)) {
    if (words(m[1]).length >= MIN_WORDS) quotes.push({ text: m[1].trim(), by: fullName(text, nameNear(text, m.index, m[0].length, names)) });
  }
  const list = nameList(text, names);
  if (!quotes.length && !list) {
    // A post that is one quote with a name on it, with no marks: "Name: words" or "words. - Name".
    const one = text.match(/^\s*([^:\n]{3,40}):\s*(.{25,400})$/s) || text.match(/^(.{25,400}?)\s*[-–]\s*([A-Z][\w .']{2,40})\s*$/s);
    if (one && names.some((n) => fold(one[0]).includes(fold(n)))) {
      const [q, by] = one[0].includes(":") && text.indexOf(":") < 40 ? [one[2], one[1]] : [one[1], one[2]];
      if (words(q).length >= MIN_WORDS) quotes.push({ text: q.trim(), by: by.trim() });
    }
  }
  return { quotes: quotes.slice(0, MAX_QUERIES), list };
}

// A surname as the post writes it in full: "Aurelius" in "Marcus Aurelius wrote" reads as "Marcus Aurelius".
function fullName(text, n) {
  if (!n || !/^[A-Za-z'-]+$/.test(n)) return n;
  const m = text.match(new RegExp(`((?:[A-Z][a-z]+ ){1,2})${n}\\b`));
  return m ? (m[1] + n).trim() : n;
}

// The name nearest a quote, within 120 characters before it or 60 after, from the known names.
function nameNear(text, at, len, names) {
  const before = fold(text.slice(Math.max(0, at - 120), at)), after = fold(text.slice(at + len, at + len + 60));
  let best = null, dist = Infinity;
  for (const n of names) {
    const k = fold(n), b = before.lastIndexOf(k), a = after.indexOf(k);
    // Distance from the end of the name, so "Marcus Aurelius" and "Aurelius" tie, and the longer wins.
    const db = b >= 0 ? before.length - (b + k.length) : Infinity, da = a >= 0 ? a : Infinity, d = Math.min(db, da);
    if (d < dist || (d === dist && best && n.length > best.length)) { best = n; dist = d; }
  }
  return best;
}

// Three or more lines of "Name: words" form a list of attributions. Counts how many lines name a
// known person and how many give any source (a link, a work's title in quotes, or a year in brackets).
function nameList(text, names) {
  const lines = text.split(/\n/).map((l) => l.replace(/^\s*[-•*\d.)]+\s*/, "")).filter((l) => /^[^:]{2,40}:\s*\S/.test(l));
  if (lines.length < 3) return null;
  const known = new Set(names.map(fold));
  const named = lines.filter((l) => known.has(fold(l.split(":")[0]).trim())).length;
  const sourced = lines.filter((l) => /https?:\/\/|\(\d{3,4}\)|["“][^"”]{3,60}["”],? (?:p\.|ch\.|book)/i.test(l)).length;
  const short = lines.filter((l) => words(l.split(":").slice(1).join(":")).length < MIN_WORDS).length;
  return { lines: lines.length, named, sourced, short };
}

// The searchable index over the bundled passages: content words to passage numbers, with each
// word's rarity. Built once, in the background worker, from quotes.json.
function buildIndex(data) {
  const postings = new Map(), passages = data.passages || [];
  passages.forEach((p, i) => {
    for (const w of new Set(content(p[2]))) { let l = postings.get(w); if (!l) postings.set(w, (l = [])); l.push(i); }
  });
  const n = Math.max(1, passages.length), idf = (w) => Math.log(1 + n / ((postings.get(w) || []).length + 1));
  return { data, postings, idf, n };
}

// How much of the quote's meaning the passage holds: the share of the quote's content words, each
// weighted by rarity, that the passage contains; and the share of the quote's word pairs in order.
function cover(q, passageText, idf) {
  const p = new Set(content(passageText)), qs = [...new Set(q)];
  const total = qs.reduce((a, w) => a + idf(w), 0) || 1;
  const have = qs.filter((w) => p.has(w)).reduce((a, w) => a + idf(w), 0);
  const pw = " " + content(passageText).join(" ") + " ", pairs = q.slice(1).map((w, i) => ` ${q[i]} ${w} `);
  const inOrder = pairs.length ? pairs.filter((pr) => pw.includes(pr)).length / pairs.length : 0;
  return { share: have / total, inOrder, matched: qs.filter((w) => p.has(w)).length, of: qs.length };
}

// The best passages for one quote: candidates share at least two rare words with it.
function searchIndex(index, quote, { limit = 3 } = {}) {
  const q = content(quote);
  if (q.length < 3) return [];
  // Every word votes by its rarity, so a short quote of common words still finds its passage.
  const votes = new Map();
  for (const w of new Set(q)) for (const i of index.postings.get(w) || []) votes.set(i, (votes.get(i) || 0) + index.idf(w));
  const exact = words(quote).join(" ");
  return [...votes.entries()].sort((a, b) => b[1] - a[1]).slice(0, 200)
    .map(([i]) => { const p = index.data.passages[i]; const c = cover(q, p[2], index.idf); return { i, ...c, exact: words(p[2]).join(" ").includes(exact) }; })
    .sort((a, b) => (b.exact - a.exact) || (b.share - a.share) || (b.inOrder - a.inOrder)).slice(0, limit);
}

const FOUND_AT = 0.85;
const CLOSE_AT = 0.6;
// A paraphrase must carry most of the quote's rare words, at least three of them, with some of its
// word pairs in the same order.
const closeEnough = (b) => b.share >= CLOSE_AT && b.matched >= Math.max(3, Math.ceil(0.6 * b.of)) && b.inOrder >= 0.2;

// One quote's answer. by: the person the post credits, if any.
function lookupQuote(index, quote, by = null) {
  const listed = matchList(index.data.misattributed || [], quote);
  if (listed) return { status: "misattributed", quote, by, entry: listed };
  const attested = matchList(index.data.attested || [], quote);
  if (attested) return { status: "attested", quote, by, entry: attested };
  const [best] = searchIndex(index, quote);
  const kind = !best ? "not-found" : best.exact || (best.share >= FOUND_AT && best.inOrder >= 0.5) ? "found" : closeEnough(best) ? "close" : "not-found";
  if (kind === "not-found") return { status: "not-found", quote, by, searched: worksBy(index.data, by) };
  const p = index.data.passages[best.i], work = index.data.works[p[0]];
  const otherAuthor = by && work.author && !fold(work.author).includes(fold(by).split(" ").pop()) && !fold(by).includes(fold(work.author).split(" ").pop());
  return { status: kind, quote, by, work, locator: p[1], passage: snippet(p[2], content(quote).slice(0, 3)), share: Math.round(best.share * 100) / 100, otherAuthor: !!otherAuthor };
}

// The curated lists match on meaning too, with a higher bar, since they hold one sentence each.
function matchList(list, quote) {
  const q = content(quote);
  if (q.length < 3) return null;
  const idf = () => 1;
  for (const e of list) { const c = cover(q, e.quote, idf); const back = cover(content(e.quote), quote, idf); if (c.share >= 0.75 && back.share >= 0.6) return e; }
  return null;
}

// The works by a credited person that the index holds, so "not found" can say where it looked.
function worksBy(data, by) {
  if (!by) return { works: (data.works || []).length, byPerson: null };
  const last = fold(by).split(" ").pop();
  return { works: (data.works || []).length, byPerson: (data.works || []).filter((w) => fold(w.author).includes(last)).map((w) => `${w.title} (${w.translator ? "trans. " + w.translator : "original"})`) };
}

return { QUOTE_DOES_NOT_PROVE, extractQuotes, buildIndex, searchIndex, FOUND_AT, CLOSE_AT, lookupQuote };
})();

// ---- persona.js
const M_persona = (() => {
// The persona account marker (project-docs/DISCOURSE.md): an account whose display name is the name
// of a well-known person who has died, such as "Arthur Schopenhauer" posting in 2026. The names come
// from Wikidata (src/ext/discourse/persons.json, CC0), and the build keeps only names no other person
// in Wikidata shares who might be alive (scripts/discourse-data.mjs persons). A second cue is
// required: the handle carries the name, or the display name says what kind of account it is.
// It never names a living person, and it says what the account is not, never what it intends.
const { fold, containsNear, editDistance } = M_text;

const PERSONA_DOES_NOT_PROVE = "A display name is chosen by whoever runs the account. Fan pages, quote accounts, parodies and tributes all use the names of people who have died. This shows only that the name belongs to someone who died, according to Wikidata.";
const CHECKMARK_NOTE = "On X, the blue checkmark has been sold as part of a paid subscription since 2023. It does not confirm who runs an account.";

// Words that say an account presents a person's work rather than being that person.
const KIND = /\b(quotes?|wisdom|philosophy|literature|daily|official|fan|fans|parody|tribute|archive|words|teachings|legacy|thoughts|writings|letters|sayings|bot|reads?|books?|now)\b/i;

const tokens = (s) => (fold(s).match(/[a-z]+/g) || []);

// The lookup over persons.json: first token to [[tokens], person].
function buildPersons(data) {
  const byFirst = new Map();
  for (const p of data.people || []) {
    const [qid, name, born, died, names] = p;
    for (const n of names || [name]) {
      const t = tokens(n);
      if (!t.length) continue;
      let l = byFirst.get(t[0]);
      if (!l) byFirst.set(t[0], (l = []));
      l.push([t, { qid, name, born, died }]);
    }
  }
  return { byFirst, source: data.source || null };
}

// The person whose full name runs, word for word, through the display name. Longest name wins.
function inDisplay(index, display) {
  const t = tokens(display);
  let best = null;
  for (let i = 0; i < t.length; i++) {
    for (const [nt, person] of index.byFirst.get(t[i]) || []) {
      if (nt.every((w, k) => t[i + k] === w) && (!best || nt.length > best.tokens.length)) best = { person, tokens: nt, extra: t.length - nt.length };
    }
  }
  return best;
}

// Does the handle carry the person's name? Each name word of five letters or more is looked for,
// with one letter of slack for six letters or more ("LeoTollstoy").
function handleCue(handle, nameTokens) {
  const h = fold(handle).replace(/[^a-z]/g, "");
  const long = nameTokens.filter((w) => w.length >= 5);
  if (!long.length) return nameTokens.join("") === h ? nameTokens.join(" ") : null;
  return long.find((w) => containsNear(h, w)) || null;
}

// account: { display, handle, verified }. Returns null, or the marker: the person, the cue that
// carried it and the rows the window shows.
function personaOf(index, account) {
  if (!index || !account || !account.display) return null;
  const hit = inDisplay(index, account.display);
  if (!hit) return null;
  const inHandle = account.handle ? handleCue(account.handle, hit.tokens) : null;
  const kindWord = hit.extra > 0 ? (account.display.match(KIND) || [])[0] : null;
  if (!inHandle && !kindWord) return null;
  const p = hit.person, years = `${yearText(p.born)} to ${yearText(p.died)}`;
  return {
    person: p, cue: inHandle ? "handle" : "display",
    label: `uses the name of ${p.name} (died ${yearText(p.died)})`,
    rows: [
      ["What Daylight Commons sees", `This account's name is the name of ${p.name} (${years}), who died ${p.died < 0 || p.died < 1900 ? "long before social media" : "in " + yearText(p.died)}. It is not that person writing.`],
      ["Why it shows", inHandle ? `The display name and the handle both carry the name ("${inHandle}").` : `The display name adds "${kindWord}" to the name.`],
      ...(account.verified ? [["The checkmark", CHECKMARK_NOTE]] : []),
      ["Source", `Wikidata ${p.qid}, from the name list that ships inside Daylight Commons.`],
      ["What it shows", PERSONA_DOES_NOT_PROVE],
    ],
  };
}

const yearText = (y) => (y == null ? "unknown" : y <= 0 ? `${1 - y} BCE` : String(y));

// Exposed for tests: a handle is "close" to a name word when one letter differs.
const nearWord = (a, b) => editDistance(fold(a), fold(b), 1) <= 1;

return { PERSONA_DOES_NOT_PROVE, CHECKMARK_NOTE, buildPersons, personaOf, yearText, nearWord };
})();

// ---- stats.js
const M_stats = (() => {
// Numbers with their sample size (project-docs/DISCOURSE.md): "45/50 replies", "8 of 25", "62% of
// 1,200 people", "n = 40". Each count gets a Wilson 95% interval, the same interval Daylight
// Commons prints for its own figures, and a note when the sample is small.
const STATS_DOES_NOT_PROVE = "An interval shows how much a count of this size can move by chance alone. It says nothing about how the sample was chosen, how the question was asked, or whether the result holds elsewhere.";
const SMALL_N = 30;

// Wilson score interval for k of n, at 95%. Returns [low, high] as proportions.
function wilson(k, n, z = 1.96) {
  if (!(n > 0) || k < 0 || k > n) return null;
  const p = k / n, d = 1 + (z * z) / n, c = (p + (z * z) / (2 * n)) / d;
  const h = (z * Math.sqrt((p * (1 - p)) / n + (z * z) / (4 * n * n))) / d;
  return [Math.max(0, c - h), Math.min(1, c + h)];
}

const num = (s) => Number(String(s).replace(/,/g, ""));
// Words that make a fraction a count of things rather than a date or a score.
const COUNT_NOUN = /^\s*(?:of\s+(?:the\s+)?)?(?:\w+\s+){0,2}?(people|persons|participants|respondents|patients|replies|responses|answers|users|voters|adults|subjects|cases|trials|runs|samples|students|children|women|men|households|doctors|experts|models|messages|posts|times|tries|attempts|items|questions|say|said|mention|mentioned|agree|agreed|chose|reported|were|are|had|have|did|got|passed|failed|correct|right|wrong|unsteered|steered)\b/i;
const DATE_LIKE = (k, n) => n <= 31 && k <= 31 && (k <= 12 || n <= 12);

// Every count in a text: { k, n, text, at, interval, small }.
function findCounts(text) {
  const t = String(text || ""), out = [], seen = new Set();
  const push = (k, n, at, len) => {
    if (!(n >= 2 && n <= 1e7 && k >= 0 && k <= n) || seen.has(at)) return;
    seen.add(at);
    out.push({ k, n, at, text: t.slice(at, at + len), interval: wilson(k, n), small: n < SMALL_N });
  };
  for (const m of t.matchAll(/\b(\d{1,3}(?:,\d{3})*|\d+)\s*\/\s*(\d{1,3}(?:,\d{3})*|\d+)\b/g)) {
    const k = num(m[1]), n = num(m[2]), after = t.slice(m.index + m[0].length, m.index + m[0].length + 40);
    if (COUNT_NOUN.test(after) || (!DATE_LIKE(k, n) && /^\s*(?:\)|$|[,.;:])/.test(after) && sameDenominator(t, n) > 1)) push(k, n, m.index, m[0].length);
  }
  for (const m of t.matchAll(/\b(\d{1,3}(?:,\d{3})*|\d+)\s+(?:out\s+)?of\s+(?:the\s+)?(\d{1,3}(?:,\d{3})*|\d+)\b/gi)) push(num(m[1]), num(m[2]), m.index, m[0].length);
  for (const m of t.matchAll(/\b(\d{1,3}(?:\.\d+)?)\s?%\s*(?:of\s+(?:the\s+)?|\(\s*n\s*=\s*)(\d{1,3}(?:,\d{3})*|\d+)/gi)) {
    const p = Number(m[1]) / 100, n = num(m[2]);
    if (p <= 1) push(Math.round(p * n), n, m.index, m[0].length);
  }
  return out.sort((a, b) => a.at - b.at);
}

// How many fractions in the text share a denominator: "45/50 ... 3/50" reads as two arms of one test.
function sameDenominator(t, n) {
  return [...t.matchAll(/\b\d+\s*\/\s*(\d+)\b/g)].filter((m) => num(m[1]) === n).length;
}

const pct = (x) => `${Math.round(x * 1000) / 10}%`;

// Two counts with the same denominator, read as two arms: do their intervals overlap?
function compareArms(counts) {
  const out = [];
  for (let i = 0; i < counts.length; i++) for (let j = i + 1; j < counts.length; j++) {
    const a = counts[i], b = counts[j];
    if (a.n !== b.n || !a.interval || !b.interval) continue;
    out.push({ a, b, overlap: a.interval[0] <= b.interval[1] && b.interval[0] <= a.interval[1] });
  }
  return out;
}

// The window's rows for a text's counts.
function countRows(counts) {
  const rows = counts.slice(0, 6).map((c) => [`"${c.text.trim()}"`, `${c.k} of ${c.n} is ${pct(c.k / c.n)}; 95% interval ${pct(c.interval[0])} to ${pct(c.interval[1])}${c.small ? `. With fewer than ${SMALL_N}, the interval is wide and one more or one fewer moves the figure a lot.` : "."}`]);
  for (const x of compareArms(counts).slice(0, 2)) rows.push(["Side by side", `${x.a.text.trim()} against ${x.b.text.trim()}: the intervals ${x.overlap ? "overlap, so chance alone could explain the gap" : "do not overlap"}.`]);
  return rows;
}

return { STATS_DOES_NOT_PROVE, SMALL_N, wilson, findCounts, compareArms, countRows };
})();

// ---- docclaim.js
const M_docclaim = (() => {
// The document-image claim check (project-docs/DISCOURSE.md). A post shows a letter, a filing or a
// report as pictures and says what it says. Daylight Commons reads each picture with its own text
// recogniser, on this device, then sets the post's key terms against the words on the pages: which
// appear, on which image, and which do not. It compares words, not meaning.
const { fold, containsNear, editDistance, STOP, snippet } = M_text;

const DOC_DOES_NOT_PROVE = "A word missing from the pages shown does not mean the document never says it: pages can be missing, the recogniser can misread a word, and a document can say the same thing in other words. A word found can be used in another sense; read the line shown.";
const MAX_TERMS = 12;
// Words too common in letters and posts to tell anything apart.
const PLAIN = new Set("would could should about after again against because before being between both claim claims every first from have having into just like made make many more most much never other over people said same says since some still such than that their them then there these they this those through very what when where which while will with without your said also does doing done even here just know made says told yesterday today".split(" "));

// The terms a post stakes its claim on: phrases in quotation marks, names (runs of capitalised
// words), amounts, and its longer content words, with two-word phrases kept together.
function keyTerms(text) {
  const t = String(text || ""), terms = [];
  const add = (s, kind) => { const k = s.trim(); if (k.length >= 3 && !terms.some((x) => fold(x.term) === fold(k))) terms.push({ term: k, kind }); };
  for (const m of t.matchAll(/["“]([^"”]{3,60})["”]/g)) add(m[1], "quoted");
  for (const m of t.matchAll(/\$?\d[\d,.]*\s*(?:million|billion|trillion|percent|%)?/gi)) if (/\d{2,}|million|billion|%/.test(m[0])) add(m[0], "amount");
  for (const m of t.matchAll(/\b([A-Z][a-z]+(?:\s+(?:[A-Z][a-z]+|of|al|de|la))*\s+[A-Z][a-z]+|[A-Z]{2,})\b/g)) add(m[1], "name");
  const ws = (fold(t).match(/[a-z]+/g) || []);
  for (let i = 0; i < ws.length - 1; i++) {
    const [a, b] = [ws[i], ws[i + 1]];
    if (a.length >= 6 && b.length >= 6 && !STOP.has(a) && !STOP.has(b) && !PLAIN.has(a) && !PLAIN.has(b)) add(`${a} ${b}`, "phrase");
  }
  for (const w of ws) if (w.length >= 7 && !STOP.has(w) && !PLAIN.has(w) && !terms.some((x) => fold(x.term).includes(w))) add(w, "word");
  return terms.slice(0, MAX_TERMS);
}

// Where one term appears in one page's text: a phrase must appear whole; a word may be off by one
// letter when it has six or more, for the recogniser's slips; a word's stem also counts
// ("clearances" finds "clearance").
function findIn(page, term) {
  const p = fold(page).replace(/\s+/g, " "), t = fold(term).replace(/\s+/g, " ");
  if (p.includes(t)) return t;
  const parts = t.split(" ");
  if (parts.length === 1) {
    const stem = t.length > 7 ? t.slice(0, Math.max(6, t.length - 3)) : t;
    if (p.includes(stem)) return stem;
    return containsNear(p, t) ? t : null;
  }
  // A phrase: the same words in a row, each long word allowed one wrong letter.
  const ws = p.match(/[a-z0-9$]+/g) || [];
  const same = (a, b) => a === b || (b.length >= 6 && editDistance(a, b, 1) <= 1);
  for (let i = 0; i + parts.length <= ws.length; i++) if (parts.every((w, k) => same(ws[i + k], w))) return ws[i];
  return null;
}

// pages: [{ text, confidence }] in the order the post shows them. Returns the found and absent terms.
function checkDocument(postText, pages) {
  const usable = (pages || []).filter((p) => p && p.text);
  const terms = keyTerms(postText);
  const found = [], absent = [];
  for (const x of terms) {
    const where = [];
    let shown = null;
    usable.forEach((p, i) => { const hit = findIn(p.text, x.term); if (hit) { where.push(i + 1); if (!shown) shown = snippet(p.text, [hit], 200); } });
    (where.length ? found : absent).push({ ...x, images: where, snippet: shown });
  }
  return { images: (pages || []).length, read: usable.length, terms: terms.length, found, absent };
}

const list = (xs) => xs.map((x) => `"${x.term}"`).join(", ");

// The window's rows for a finished check.
function docRows(r) {
  if (!r || !r.terms) return [["Document check", "The post has no terms to look for."]];
  const n = r.read, img = `${n} ${n === 1 ? "image" : "images"} read`;
  const rows = [["Pages", `${img} of the ${r.images} the post shows. Pages the post does not show were not checked.`]];
  if (r.absent.length) rows.push(["Not on the pages shown", list(r.absent)]);
  if (r.found.length) rows.push(["On the pages shown", r.found.map((x) => `"${x.term}" (image ${x.images.join(", ")})`).join("; ")]);
  for (const x of r.found.filter((f) => f.kind !== "name" && f.kind !== "amount").slice(0, 3)) rows.push([`"${x.term}" in context`, x.snippet]);
  rows.push(["What it shows", DOC_DOES_NOT_PROVE]);
  return rows;
}

return { DOC_DOES_NOT_PROVE, keyTerms, findIn, checkDocument, docRows };
})();

// ---- corrections.js
const M_corrections = (() => {
// Correction replies (project-docs/DISCOURSE.md): among the replies the page has loaded, the ones
// that name a specific error in the post or bring a source, ranked by the source they bring. Likes,
// followers and the reply's side never enter the ranking, and no word list here names a party, a
// side or a group (tests/discourse.symmetry.test.js swaps the sides of fixture threads and expects
// the same order). A raised reply is a challenge to read, never a verdict.
const { content, fold } = M_text;

const CORRECTIONS_DOES_NOT_PROVE = "A reply that brings a source or names an error can still be wrong. Daylight Commons ranks replies by the kind of source they cite and how specifically they answer the post, not by whether they are right.";

// Reference and primary-record hosts. A link to one of these is the strongest kind of source a reply
// can bring; any other web page counts for less; links to social posts count for nothing.
const PRIMARY = /(^|\.)(doi\.org|arxiv\.org|pubmed\.ncbi\.nlm\.nih\.gov|ncbi\.nlm\.nih\.gov|courtlistener\.com|supremecourt\.gov|legislation\.gov\.uk|eur-lex\.europa\.eu|congress\.gov|govinfo\.gov|dni\.gov|ohchr\.org|sec\.gov|census\.gov|gutenberg\.org|archive\.org|loc\.gov|nationalarchives\.gov\.uk|un\.org|who\.int|oecd\.org|worldbank\.org|imf\.org|data\.gov)$/;
const REFERENCE = /(^|\.)(wikipedia\.org|britannica\.com|plato\.stanford\.edu|iep\.utm\.edu|oxfordreference\.com|jstor\.org|nature\.com|science\.org|thelancet\.com|nejm\.org|bmj\.com|cell\.com|springer\.com|wiley\.com|tandfonline\.com|sciencedirect\.com|quoteinvestigator\.com|wikiquote\.org|snopes\.com|factcheck\.org|fullfact\.org|politifact\.com)$|\.(gov|edu|mil|int)$|\.(gov|ac|edu)\.[a-z]{2}$/;
const SOCIAL = /(^|\.)(x\.com|twitter\.com|t\.co|facebook\.com|instagram\.com|tiktok\.com|threads\.(net|com)|bsky\.app|reddit\.com|youtube\.com|youtu\.be)$/;

// Phrases that name an error or a correction. Neutral by construction: they describe the move.
const CUES = [
  /\bcorrections?\b/i, /\b(?:not|isn'?t|wasn'?t|aren'?t) (?:true|accurate|correct|what (?:he|she|they|it) said)\b/i,
  /\b(?:is|was|that'?s|this is) (?:false|wrong|inaccurate|incorrect|misleading|a misquote|misattributed)\b/i,
  /\bmisattribut\w*/i, /\bnever (?:said|wrote|happened)\b/i, /\b(?:in fact|actually|factually)\b/i,
  /\baccording to\b/i, /\bthe (?:source|record|transcript|original|full quote|paper|study|data) (?:says|shows|is)\b/i,
  /\b(?:first|originally) (?:published|said|written|appeared)\b/i, /\bfake quote\b/i, /\bout of context\b/i,
];

const hostOf = (u) => { try { return new URL(u).hostname.toLowerCase().replace(/^www\./, ""); } catch { return ""; } };
function sourceKind(url) {
  const h = hostOf(url);
  if (!h) return null;
  return PRIMARY.test(h) ? "primary" : REFERENCE.test(h) ? "reference" : SOCIAL.test(h) ? "social" : "web";
}
const KIND_SCORE = { primary: 3, reference: 2.5, web: 1, social: 0 };

// What a reply shares with the post it answers: content words of four letters or more, numbers and
// years. Two or more shared items make a cue "specific". The length bar is low on purpose: a higher
// one would treat "left" and "right" differently.
function shared(post, reply) {
  const p = new Set(content(post).filter((w) => w.length >= 4 || /^\d{2,}$/.test(w)));
  return [...new Set(content(reply))].filter((w) => p.has(w));
}

// One reply's reading: its sources, its quoted passage, its cues and what it shares with the post.
function readReply(postText, r) {
  const kinds = (r.links || []).map(sourceKind).filter(Boolean);
  const best = kinds.sort((a, b) => KIND_SCORE[b] - KIND_SCORE[a])[0] || null;
  const quoted = (String(r.text).match(/["“]([^"”]{40,})["”]/) || [])[1] || null;
  const cues = CUES.filter((re) => re.test(r.text)).length;
  const common = shared(postText, r.text);
  const specific = common.length >= 2;
  const score = (best ? KIND_SCORE[best] : 0) + (quoted ? 1.5 : 0) + (cues && specific ? 1 + Math.min(1, common.length / 6) : 0);
  const raised = (best && best !== "social" && (common.length >= 1 || cues > 0)) || (quoted && specific) || (cues > 0 && specific);
  // The reply's origin: the host of its best link. Replies with the same origin are one witness, not
  // several (src/core/discourse/sheets.js independence).
  const origin = best && best !== "social" ? hostOf((r.links || []).find((u) => sourceKind(u) === best)) : null;
  return { id: r.id, author: r.author, score: Math.round(score * 100) / 100, raised: !!raised, source: best, origin, quoted: !!quoted, cues, shared: common.slice(0, 6) };
}

// The raised replies, best source first; ties keep the page's order. Likes are never read.
function rankCorrections(post, replies) {
  const text = (post && post.text) || "";
  return (replies || []).map((r, order) => ({ ...readReply(text, r), order, text: r.text }))
    .filter((x) => x.raised && fold(x.author || "") !== fold((post && post.author) || "\u0000"))
    .sort((a, b) => b.score - a.score || a.order - b.order);
}

const why = (x) => [x.source ? `links a ${x.source === "primary" ? "primary record" : x.source === "reference" ? "reference work" : "web page"}` : null, x.quoted ? "quotes a passage" : null, x.cues && x.shared.length >= 2 ? `names an error about ${x.shared.slice(0, 3).join(", ")}` : null].filter(Boolean).join("; ");

// The window's rows: up to five raised replies, each with why it was raised.
function correctionRows(ranked) {
  const rows = ranked.slice(0, 5).map((x) => [`@${x.author}`, `"${String(x.text).replace(/\s+/g, " ").slice(0, 160)}${x.text.length > 160 ? " …" : ""}" (${why(x)})`]);
  rows.push(["How they are ranked", "By the kind of source each reply brings, then by how specifically it answers the post. Likes and followers are not read."]);
  rows.push(["What it shows", CORRECTIONS_DOES_NOT_PROVE]);
  return rows;
}

return { CORRECTIONS_DOES_NOT_PROVE, sourceKind, readReply, rankCorrections, correctionRows };
})();

// ---- argument-measured.js
const M_argument_measured = (() => {
// The argument lens's gate, written by scripts/eval-argument-gold.mjs --write from two people's
// annotations of the held-out gold passages (data/argument/passages.json). A role shows by default only
// when its precision is 0.8 or more from at least 3 hits; boundaries per language need precision 0.8
// and recall 0.7. Until annotations exist every entry is null and nothing passes.
const ARGUMENT_GATE = { premise: null, "minor premise": null, "supporting premise": null, assumption: null, conclusion: null, turn: null };
const BOUNDARY_GATE = { la: null, en: null, fr: null, es: null, pt: null };
const GATE_SOURCE = "awaiting two annotators";

return { ARGUMENT_GATE, BOUNDARY_GATE, GATE_SOURCE };
})();

// ---- cards.js
const M_cards = (() => {
// The window's signs for the discourse checks, in the shape src/ext/signals.js draws: { label, fam,
// level, cat, rows }. All are info level: these checks are new and not yet measured on real threads
// (project-docs/DISCOURSE.md), so none of them raises a warning.
const { QUOTE_DOES_NOT_PROVE } = M_quotes;
const { ARGUMENT_GATE } = M_argument_measured;
const { countRows, STATS_DOES_NOT_PROVE } = M_stats;
const { docRows } = M_docclaim;
const { correctionRows } = M_corrections;

const sign = (label, fam, cat, rows) => ({ label, fam, level: "info", cat, rows });
const workLine = (w) => `${w.title}, ${w.author}${w.translator ? `, translated by ${w.translator}` : ""}${w.year ? ` (${w.year})` : ""}`;
const link = (w) => (w.link ? [["Read it", { links: [[w.link.replace(/^https?:\/\//, "").slice(0, 48), w.link]] }]] : []);

// One quote lookup's rows.
function quoteRows(r) {
  const q = ["Quote", `"${r.quote.length > 160 ? r.quote.slice(0, 160) + " …" : r.quote}"${r.by ? `, credited to ${r.by}` : ""}`];
  if (r.status === "found" || r.status === "close") {
    return [q, ["Found", r.status === "found" ? `In ${workLine(r.work)}, ${r.locator}.` : `A close paraphrase of ${workLine(r.work)}, ${r.locator}. The wording differs; about ${Math.round(r.share * 100)}% of its meaning words are in the passage.`],
      ["The passage", r.passage], ...(r.otherAuthor ? [["Credited to", `The post credits ${r.by}; the passage is from ${r.work.author}.`]] : []), ...link(r.work)];
  }
  if (r.status === "misattributed") {
    const e = r.entry;
    return [q, ["Listed as misattributed", `Commonly credited to ${e.creditedTo}. ${e.finding}`], ["Source", { links: [[e.sourceTitle, e.source]] }]];
  }
  if (r.status === "attested") {
    const e = r.entry;
    return [q, ["Attested", `${e.finding} The work is not in the index, so the wording shown is from the cited source.`], ["Source", { links: [[e.sourceTitle, e.source]] }]];
  }
  const s = r.searched || {};
  return [q, ["Not found", `Not in the ${s.works || 0} works the index holds${s.byPerson && s.byPerson.length ? `, including ${s.byPerson.slice(0, 3).join("; ")}` : r.by ? `, none of them by ${r.by}` : ""}. This proves nothing: most of what anyone wrote is not in the index.`]];
}

const STATUS = { found: "quote found", close: "close paraphrase", misattributed: "quote listed as misattributed", attested: "quote attested", "not-found": "quote not found in the index" };

function quoteSigns(results, list) {
  const out = (results || []).map((r) => sign(STATUS[r.status], "quote-source", "sources", [...quoteRows(r), ["What it shows", QUOTE_DOES_NOT_PROVE]]));
  if (list && list.lines >= 3) {
    out.push(sign(`${list.lines} lines credited to names, ${list.sourced} sourced`, "quote-list", "sources", [
      ["What Daylight Commons sees", `${list.lines} lines each credit a named person${list.named ? ` (${list.named} of them names Daylight Commons knows)` : ""}. ${list.sourced === 0 ? "None gives" : `${list.sourced} give`} a source.`],
      ...(list.short ? [["Too short to look up", `${list.short} ${list.short === 1 ? "line is" : "lines are"} under five words, too short to find in any text.`]] : []),
      ["What it shows", "A list of one-line sayings without sources is a common format for misattributed quotes. Some lines may still be fair summaries of a person's view."],
    ]));
  }
  return out;
}

function personaSign(p) {
  return p ? [sign(p.label, "persona", "account", p.rows)] : [];
}

function countSigns(counts, fromImage = false) {
  if (!counts || !counts.length) return [];
  return [sign(`${counts.length === 1 ? "a count" : counts.length + " counts"} with ${counts.length === 1 ? "its" : "their"} sample size${fromImage ? " (in image)" : ""}`, "sample-size", "sources",
    [...countRows(counts), ...(fromImage ? [["Read from", "the image, by Daylight Commons' own text recogniser"]] : []), ["What it shows", STATS_DOES_NOT_PROVE]])];
}

function docSign(r) {
  if (!r) return [];
  const label = r.absent.length ? `${r.absent.length} of the post's terms not on the pages shown` : "the post's terms are on the pages shown";
  return [sign(label, "doc-claim", "sources", docRows(r))];
}

function correctionSign(ranked) {
  if (!ranked || !ranked.length) return [];
  return [sign(`${ranked.length} ${ranked.length === 1 ? "reply brings a source or names" : "replies bring a source or name"} an error`, "correction-replies", "sources", correctionRows(ranked))];
}


// A sign's rows as plain text for a study note: "Heading: value", links as their addresses, and
// buttons left out. The sidecar keeps these under "## Analysis: <label>" (project-docs/SIDECAR-FORMAT.md).
function rowText([h, v]) {
  if (v && typeof v === "object") return v.links ? `${h ? h + ": " : ""}${v.links.map(([t, u]) => `${t} (${u})`).join("; ")}` : null;
  return h ? `${h}: ${v}` : String(v);
}

// The discourse signs of one post as study notes and the ids of the analyses they carry.
function studyNotes(signs) {
  const keep = (signs || []).filter((s) => s && s.fam && s.rows && !s.rows.some(([, v]) => v && typeof v === "object" && v.action));
  return {
    notes: keep.map((s) => ({ label: `Analysis: ${s.label}`, text: s.rows.map(rowText).filter(Boolean).join("\n") })),
    analysis: [...new Set(keep.map((s) => s.fam))],
  };
}

// The argument lens's gate (project-docs/ARGUMENT-LENS.md): a role shows by default only when its own
// held-out precision is 0.8 or more, from at least 3 hits, against two annotators' agreement. No role
// has been measured yet, so every role is shown as a plain segment unless "Every argument role" is on.
const roleShown = (role, all, gate = ARGUMENT_GATE) => all || !!(gate[role] && gate[role].precision >= 0.8 && gate[role].hits >= 3);

function argumentSign(r, { all = false, gate = ARGUMENT_GATE } = {}) {
  if (!r || r.segments.length < 2 || !r.segments.some((s) => s.opener)) return [];
  const rows = r.segments.map((s, i) => [roleShown(s.role, all, gate) ? `${i + 1}. ${s.role}` : `${i + 1}. segment`, `${s.opener ? `[${s.opener.form}] ` : ""}${s.text.length > 140 ? s.text.slice(0, 140) + " …" : s.text}`]);
  const moves = r.units.map((u) => u.movement);
  return [sign(`argument: ${r.segments.length} segments, ${r.units.length} ${r.units.length === 1 ? "movement" : "movements"}`, "argument-structure", "language", [
    ...rows,
    ["Movements", moves.join(", ")],
    ["Language", r.lang],
    ["Roles", all ? "Every role is shown, measured or not; none has passed its held-out gate yet." : "Roles show once their held-out precision passes; until then each part reads as a segment."],
    ["What it shows", "A connective is what the author says links two claims. The lens shows that the author marks a part as following; it does not show that it follows."],
  ])];
}

function claimTypeSign(types) {
  if (!types || !types.length) return [];
  const kinds = [...new Set(types.map((t) => t.type))];
  return [sign(`claims: ${kinds.join(", ")}`, "claim-type", "language", [
    ...types.slice(0, 8).map((t) => [t.type, `"${t.text.length > 120 ? t.text.slice(0, 120) + " …" : t.text}" (${t.cue})`]),
    ["What it shows", "A claim type is read from wording cues, so a sentence can carry two kinds, and irony or quotation can mislead the cue. It says what kind of claim the words make, not whether the claim is true."],
  ])];
}

function gapSign(gaps) {
  if (!gaps || !gaps.length) return [];
  return [sign(`${gaps.length} inference ${gaps.length === 1 ? "gap" : "gaps"}`, "inference-gap", "language", [
    ...gaps.slice(0, 5).map((g) => [g.kind === "mind" ? `about someone's mind ("${g.cue}")` : `conclusion ("${g.cue}")`, `${g.why} "${g.text.length > 120 ? g.text.slice(0, 120) + " …" : g.text}"`]),
    ["What it shows", "An inference can be sound even when its words are new, and a claim about someone's intent can be right. The marker shows where the post goes beyond what it states; it does not say the conclusion is wrong."],
  ])];
}

function reframingSign(r, rows) {
  return r ? [sign(`reframes ${r.shared.length} named parts of its sources`, "reframing", "sources", rows(r))] : [];
}

return { quoteSigns, personaSign, countSigns, docSign, correctionSign, studyNotes, roleShown, argumentSign, claimTypeSign, gapSign, reframingSign };
})();

// ---- sheets.js
const M_sheets = (() => {
// Truth as sheets (project-docs/DISCOURSE.md): a claim is a sheet laid over what it rests on. The
// post sits on top, the replies that bring a source beneath it, the primary documents at the ground.
// Each sheet's ink coverage is its reach, so a claim seen 230,000 times covers a correction seen 627
// times. Lifting a sheet shows what lies under it.
//
// The compositing engine is the workspace medium's sheet engine (lib/medium/sheets.mjs), copied here
// unchanged so the extension ships with no dependency. It has no single law: each sheet carries its own
// (multiply, density_add, weber, screen), and where sheets meet each applies its own on its side. Every
// sheet here is a post seen through the ones above it, so every sheet uses the same law, weber
// (Albers XX-1, a = 29.75). tests/discourse.sheets.test.js holds the constants and, when
// SUPERFRAME_SHEETS points at the original module, checks the two give the same colours.

const DENSITY_W = 0.243;
const WEBER = 29.75;
const hexLin = (h) => { const n = parseInt(h.slice(1), 16); return [16, 8, 0].map((s) => { const c = ((n >> s) & 255) / 255; return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4; }); };
const perceived = (D, unit) => (unit > 1e-6 ? unit * Math.log1p(WEBER * D / unit) / Math.log1p(WEBER) : D);

// one pixel: paper (linear rgb) under the sheets in print order (copied from the medium's composite)
function composite(paper, sheets) {
  const c = paper.slice(), D = [0, 0, 0], U = [0, 0, 0];
  let inked = 0, anyWeber = false;
  for (const s of sheets) {
    const law = s.law ?? "multiply", cov = s.cover ?? 1;
    if (cov <= 0) continue;
    for (let k = 0; k < 3; k++) {
      const t = 1 - cov * (1 - s.ink[k]);
      if (law === "multiply") c[k] *= t;
      else if (law === "density_add") c[k] *= inked > 0 ? Math.pow(Math.max(1e-4, t), 1 - (1 - DENSITY_W) * inked) : t;
      else if (law === "screen") c[k] = 1 - (1 - c[k]) * (1 - cov * s.ink[k]);
      else { const d = -Math.log(Math.max(1e-4, t)); D[k] += d; if (d > U[k]) U[k] = d; anyWeber = true; }
    }
    if (law === "density_add") inked = Math.min(1, inked + cov);
  }
  if (anyWeber) for (let k = 0; k < 3; k++) c[k] *= Math.exp(-perceived(D[k], U[k]));
  return c;
}

// The medium's printSheets: a paper colour and sheets, each sheet's own law or the default.
function printSheets(paper, sheets, { law = "weber" } = {}) {
  const P = typeof paper === "string" ? hexLin(paper) : paper;
  return composite(P, sheets.map((s) => ({ ...s, law: s.law ?? law })));
}
const toHex = (lin) => "#" + lin.map((c) => Math.round(255 * (c <= 0.0031308 ? 12.92 * c : 1.055 * c ** (1 / 2.4) - 0.055))).map((v) => Math.max(0, Math.min(255, v)).toString(16).padStart(2, "0")).join("");

// The canon's ground and verdict inks. The verdict is about sourcing only, the same for every sheet:
// a post that links a primary record or a reference work prints in verified, one that does not in
// drift, whatever it says and whoever wrote it. A primary document is the ground.
const PAPER = "#ebe5d8";
const INKS = { sourced: "#0a6b61", unsourced: "#8f3a19", document: "#16130f" };

// thread: { claim: { text, reach }, corrections: [{ text, reach, origin }], documents: [{ title, url }] }
// reach is the views the site showed (null when it showed none). Corrections that share an origin are
// one sheet: many replies from one source are a metamer of independence, not several witnesses.
function buildSheets(thread) {
  const claim = thread.claim || {}, top = Math.max(1, Number(claim.reach) || 0, ...(thread.corrections || []).map((c) => Number(c.reach) || 0));
  const byOrigin = new Map();
  for (const c of thread.corrections || []) {
    const k = c.origin || `reply:${byOrigin.size}`, g = byOrigin.get(k);
    if (g) { g.replies += 1; g.reach += Number(c.reach) || 0; } else byOrigin.set(k, { kind: "correction", text: c.text, origin: c.origin || null, sourced: !!c.origin, replies: 1, reach: Number(c.reach) || 0 });
  }
  const sheets = [
    { kind: "claim", text: claim.text || "", origin: claim.origin || null, sourced: !!claim.origin, replies: 1, reach: Number(claim.reach) || 0 },
    ...byOrigin.values(),
    ...(thread.documents || []).map((d) => ({ kind: "document", text: d.title, origin: d.url || null, replies: 0, reach: null })),
  ].map((s) => ({ ...s, cover: s.reach == null ? 0 : s.reach / top, ink: s.kind === "document" ? INKS.document : s.sourced ? INKS.sourced : INKS.unsourced }));
  // A document has no reach readout, so it prints no ink: it is the ground the sheets lie on, named.
  // What each sheet looks like with everything above it lifted: it over the sheets beneath it, printed
  // from the ground up (documents first, the claim last).
  return sheets.map((s, i) => {
    const under = sheets.slice(i).reverse().map((x) => ({ ink: hexLin(x.ink), cover: x.cover }));
    return { ...s, seen: toHex(printSheets(PAPER, under)), share: s.reach == null ? null : Math.round(s.cover * 10000) / 100 };
  });
}

// How many independent origins the corrections rest on, against how many replies carry them.
function independence(sheets) {
  const c = sheets.filter((s) => s.kind === "correction");
  return { replies: c.reduce((a, s) => a + s.replies, 0), origins: c.length };
}

return { DENSITY_W, WEBER, hexLin, composite, printSheets, PAPER, INKS, buildSheets, independence };
})();

// ---- parts.js
const M_parts = (() => {
// The discourse results as a parts tree (refdb.parts/1, the reference library's study format: concept
// > layer > part > property, each property labelled observed, measured or inferred with its method),
// so a claim study is the same kind of object as an art study and joins the same concept layers.
const prop = (property, value, label, method, unit = null) => ({ property, value, ...(unit ? { unit } : {}), label, method });

function quoteLayer(q) {
  if (!q || (!q.results.length && !q.list)) return null;
  const parts = q.results.map((r) => ({ name: r.quote.slice(0, 120), tags: [r.status], properties: [
    prop("status", r.status, "measured", "quote finder: rarity-weighted word match over the bundled index"),
    ...(r.by ? [prop("credited to", r.by, "observed", "the post's own words")] : []),
    ...(r.work ? [prop("source", `${r.work.title}, ${r.work.author}${r.work.translator ? `, trans. ${r.work.translator}` : ""}, ${r.locator}`, "measured", "index match"), prop("share of meaning words", r.share, "measured", "rarity-weighted share", "0..1")] : []),
    ...(r.entry ? [prop("finding", r.entry.finding, "observed", `cited: ${r.entry.source}`)] : []),
  ] }));
  if (q.list) parts.push({ name: "list of attributions", tags: ["quote-list"], properties: [prop("lines", q.list.lines, "measured", "line count"), prop("sourced", q.list.sourced, "measured", "lines with a source"), prop("too short to look up", q.list.short, "measured", "lines under five words")] });
  return { name: "quotes", parts };
}

function docLayer(d) {
  if (!d) return null;
  return { name: "document pages", parts: [
    ...d.absent.map((x) => ({ name: x.term, tags: ["absent", x.kind], properties: [prop("on the pages shown", false, "measured", `word match over ${d.read} of ${d.images} images read by Daylight's recogniser`)] })),
    ...d.found.map((x) => ({ name: x.term, tags: ["found", x.kind], properties: [prop("images", x.images, "measured", "word match"), prop("line", x.snippet, "observed", "recogniser output")] })),
  ] };
}

function countLayer(counts) {
  if (!counts || !counts.length) return null;
  return { name: "counts", parts: counts.map((c) => ({ name: c.text.trim(), tags: c.small ? ["small sample"] : [], properties: [prop("k", c.k, "observed", "the post"), prop("n", c.n, "observed", "the post"), prop("95% interval", c.interval.map((v) => Math.round(v * 1000) / 1000), "measured", "Wilson score", "proportion")] })) };
}

function correctionLayer(ranked, independence) {
  if (!ranked || !ranked.length) return null;
  return { name: "correction replies", parts: [
    ...ranked.map((x) => ({ name: `@${x.author}`, tags: [x.source || "no link"], properties: [prop("score", x.score, "measured", "source kind, then specificity; likes not read"), prop("shared terms", x.shared, "measured", "content words shared with the post")] })),
    ...(independence ? [{ name: "independence", tags: ["metamer"], properties: [prop("replies", independence.replies, "measured", "raised replies"), prop("independent origins", independence.origins, "measured", "distinct sources; replies from one source count once")] }] : []),
  ] };
}

function personaLayer(p) {
  return p ? { name: "account", parts: [{ name: p.person.name, tags: ["persona"], properties: [prop("uses the name of", `${p.person.name} (${p.person.qid})`, "measured", "Wikidata name match with a second cue"), prop("cue", p.cue, "observed", "handle or display name")] }] } : null;
}

function argumentLayer(a) {
  if (!a || a.segments.length < 2) return null;
  return { name: "argument structure", parts: a.segments.map((s, i) => ({ name: `segment ${i + 1}`, tags: [s.role, ...(s.opener ? [s.opener.form] : [])], properties: [
    prop("text", s.text, "observed", "the post"), prop("role", s.role, "inferred", "argument lens: connective and position; role precision not yet measured"),
    ...(s.opener ? [prop("connective", s.opener.form, "measured", `lexicon match (${a.lang}); roles it can take: ${s.opener.roles.join(", ")}`)] : []),
  ] })).concat(a.units.map((u, i) => ({ name: `movement ${i + 1}`, tags: [u.movement], properties: [prop("segments", u.segments.map((k) => k + 1), "measured", "units cut at continuation connectives and conclusions"), prop("movement", u.movement, "inferred", "opening connective and shared words with the previous conclusion")] }))) };
}

function claimLayer(types, gaps, reframe) {
  const parts = [
    ...(types || []).map((t) => ({ name: t.text.slice(0, 120), tags: [t.type], properties: [prop("claim type", t.type, "inferred", `wording cue: ${t.cue}`)] })),
    ...(gaps || []).map((g) => ({ name: g.text.slice(0, 120), tags: ["inference gap", g.kind], properties: [prop("gap", g.why, "inferred", g.kind === "mind" ? `mind-reading cue "${g.cue}"` : "conclusion words absent from the premises")] })),
    ...(reframe ? [{ name: "reframing", tags: ["isomer"], properties: [prop("shared names", reframe.shared, "measured", "names found in the sources beneath"), prop("stated only to deny", reframe.denied, "measured", "negation within 80 characters before"), prop("in no source", reframe.added, "measured", "word match over the sources beneath")] }] : []),
  ];
  return parts.length ? { name: "claims", parts } : null;
}

// post: { site, postUrl, handle, author }; r: the results for one post.
function discourseParts(post, r) {
  const layers = [quoteLayer(r.quotes), docLayer(r.doc), countLayer(r.counts), correctionLayer(r.corrections, r.independence), personaLayer(r.persona), argumentLayer(r.argument), claimLayer(r.types, r.gaps, r.reframing)].filter(Boolean);
  return {
    format: "refdb.parts/1", study: null,
    source: { site: post.site || null, postUrl: post.postUrl || null, author: { name: post.author || null, handle: post.handle || null } },
    concepts: [{ name: "Discourse checks", label: "measured", by: "code", layers }],
  };
}

return { discourseParts };
})();

// ---- argument-cues.js
const M_argument_cues = (() => {
// Connectives by logical role, for the argument lens (src/core/discourse/argument.js). Seeded from the
// reference library's study of Aliocha's reading method (2026-10-25) and the grammar of each language.
// Each form lists every role it can take; the lens picks one by position. "clauseStart" forms count only
// at the start of a sentence or after a comma, colon or semicolon, because elsewhere they are something
// else (Portuguese "se" is mostly a pronoun; English "as" and "for" mostly are not connectives).
// Roles: conclusion, continuation, reversal, concession, cause, condition, minor, example.

const L = (spec) => Object.entries(spec).flatMap(([roles, forms]) => forms.split("|").map((f) => ({ form: f, roles: roles.split(",") })));

const CUES = {
  en: L({
    "conclusion": "therefore|thus|hence|consequently|it follows that|so it follows|accordingly|which means|that means|this means|would mean|proves that",
    "continuation": "moreover|furthermore|in addition|besides|further",
    "reversal": "however|nevertheless|nonetheless|on the contrary|on the other hand|on the other side",
    "reversal,minor": "but|yet",
    "minor,continuation": "now",
    "concession": "although|though|even if|even though|granted that",
    "cause": "because|given that|in that",
    "cause,continuation": "since",
    "condition": "if|unless|provided that",
    "example": "for example|for instance",
    "conclusion,continuation": "so",
  }),
  pt: L({
    "conclusion": "portanto|logo|por conseguinte|por isso|consequentemente|dessa forma|desse modo|segue-se que",
    "conclusion,example": "assim",
    "conclusion,condition": "então",
    "continuation": "além disso|ademais|outrossim|em seguida",
    "reversal": "porém|contudo|todavia|entretanto|no entanto|ao contrário",
    "reversal,minor": "mas",
    "minor": "ora",
    "concession": "embora|ainda que|mesmo que|apesar de|conquanto",
    "cause": "porque|visto que|já que|uma vez que|dado que",
    "cause,conclusion": "pois",
    "condition": "se|caso|desde que",
    "example": "por exemplo",
  }),
  es: L({
    "conclusion": "por lo tanto|por tanto|así pues|por consiguiente|en consecuencia|de modo que",
    "conclusion,continuation": "luego",
    "continuation": "además|asimismo|por otra parte",
    "reversal": "sin embargo|no obstante|en cambio|por el contrario",
    "reversal,minor": "pero",
    "minor": "ahora bien",
    "concession": "aunque|a pesar de|si bien|aun cuando",
    "cause": "porque|ya que|puesto que|dado que",
    "cause,conclusion": "pues",
    "condition": "si|siempre que|a menos que",
    "example": "por ejemplo",
  }),
  fr: L({
    "conclusion": "donc|par conséquent|en conséquence|il s'ensuit que|c'est pourquoi",
    "conclusion,example": "ainsi",
    "continuation": "de plus|en outre|par ailleurs",
    "reversal": "cependant|pourtant|toutefois|néanmoins|au contraire",
    "reversal,minor": "mais",
    "minor,reversal": "or",
    "concession": "bien que|quoique|même si|encore que",
    "cause": "parce que|car|puisque|étant donné que",
    "condition": "si|à condition que|à moins que",
    "example": "par exemple",
  }),
  la: L({
    "conclusion": "ergo|igitur|itaque|ideo|relinquitur quod|sequitur quod|videtur quod",
    "conclusion,cause": "unde",
    "continuation": "praeterea|item|insuper",
    "reversal": "tamen|verum|sed contra",
    "minor,reversal": "sed|atqui",
    "minor,continuation,reversal": "autem",
    "concession": "licet|quamvis|etsi|quamquam",
    "cause": "quia|nam|enim|quoniam",
    "cause,concession": "cum",
    "condition": "si|nisi|dummodo",
    "example": "sicut|ut dicit|ut patet",
  }),
};

// Forms that count only at a clause start (see above), per language.
const CLAUSE_START = { en: new Set(["so", "now", "yet", "since", "if"]), pt: new Set(["se", "caso", "assim", "então", "ora", "logo"]), es: new Set(["si", "luego", "pues"]), fr: new Set(["or", "si", "ainsi"]), la: new Set(["si", "cum", "item"]) };

// Postpositive Latin particles sit second in their clause ("finiti autem", "Deum enim"); they open the
// clause they sit in.
const POSTPOSITIVE = { la: new Set(["autem", "enim", "vero", "igitur", "tamen"]) };

const LANGS = Object.keys(CUES);

return { CUES, CLAUSE_START, POSTPOSITIVE, LANGS };
})();

// ---- argument.js
const M_argument = (() => {
// The argument lens (project-docs/ARGUMENT-LENS.md), after the reading method in Aliocha's notes on the
// Summa: split a passage into segments, mark the connective that opens each one, give each segment a
// role by its position in the argument (premise, minor premise, supporting premise, assumption,
// conclusion, turn), and group segments into movements (a list of arguments, a chain, a turn).
// A connective is what the author says links two claims. The lens shows "the author marks this as
// following", never "this follows".
const { CUES, CLAUSE_START, POSTPOSITIVE, LANGS } = M_argument_cues;
const { content } = M_text;

const LETTER = "\\p{L}";
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const COMPILED = Object.fromEntries(LANGS.map((l) => [l, CUES[l].slice().sort((a, b) => b.form.length - a.form.length)
  .map((c) => ({ ...c, re: new RegExp(`(?<!${LETTER})${esc(c.form).replace(/ /g, "\\s+")}(?!${LETTER})`, "giu") }))]));

// Strong punctuation ends a segment; a comma does not. A full stop after these abbreviations does not.
const ABBREV = new Set(["mr", "mrs", "ms", "dr", "st", "vs", "cf", "eg", "ie", "e.g", "i.e", "p", "pp", "ch", "art", "q", "obj", "ad", "no", "sr", "sra", "m", "mme"]);
const STRONG = /[.;!?]/;
// Where the clause a position sits in starts: after strong punctuation or a colon, or at the start.
function clauseStartAt(text, i) {
  let j = i - 1;
  while (j >= 0 && /\s/.test(text[j])) j--;
  return j < 0 || /[.;:!?(“"]/.test(text[j]) ? "strong" : text[j] === "," ? "comma" : null;
}
// The word before position i, and where it starts.
function prevWord(text, i) {
  const m = text.slice(0, i).match(/([\p{L}\d'-]+)\s*$/u);
  return m ? { word: m[1], at: i - m[0].length } : null;
}

// Every connective in the text: { start, end, form, roles, clause: "strong" | "comma" | null }.
function findConnectives(text, lang) {
  const out = [], taken = [];
  for (const c of COMPILED[lang] || []) {
    for (const m of text.matchAll(c.re)) {
      const start = m.index, end = start + m[0].length;
      if (taken.some(([a, b]) => start < b && end > a)) continue;
      let clause = clauseStartAt(text, start);
      if (!clause && POSTPOSITIVE[lang] && POSTPOSITIVE[lang].has(c.form)) { const p = prevWord(text, start); if (p) clause = clauseStartAt(text, p.at); }
      if (CLAUSE_START[lang] && CLAUSE_START[lang].has(c.form) && !clause) continue;
      taken.push([start, end]);
      out.push({ start, end, form: m[0].toLowerCase().replace(/\s+/g, " "), roles: c.roles, clause });
    }
  }
  return out.sort((a, b) => a.start - b.start);
}

// The language whose connectives the text uses most, or the one the site gave.
function guessLang(text, given = null) {
  if (given && CUES[given]) return given;
  let best = "en", n = 0;
  for (const l of LANGS) { const k = findConnectives(text, l).length; if (k > n) { best = l; n = k; } }
  return best;
}

// Segments: cut at strong punctuation. Each keeps the connectives in its first three words.
function segment(text, lang) {
  const cons = findConnectives(text, lang), segs = [];
  let start = 0;
  const push = (end) => {
    const raw = text.slice(start, end), lead = raw.length - raw.trimStart().length, s = start + lead, e = start + raw.trimEnd().length;
    if (e > s && /[\p{L}\d]/u.test(text.slice(s, e))) {
      const words = [...text.slice(s, e).matchAll(/[\p{L}\d'-]+/gu)], third = words[2] ? s + words[2].index + words[2][0].length : e;
      segs.push({ start: s, end: e, text: text.slice(s, e), openers: cons.filter((c) => c.start >= s && c.start < third), inner: cons.filter((c) => c.start >= third && c.start < e) });
    }
    start = end;
  };
  let quoted = false;
  for (let i = 0; i < text.length; i++) {
    if (/["\u201c\u201d]/.test(text[i])) quoted = text[i] === "\u201c" ? true : text[i] === "\u201d" ? false : !quoted;
    // a stop inside quotation marks, or not followed by a space or the end (a URL, "U.S."), does not cut
    if (!STRONG.test(text[i]) || quoted || (i + 1 < text.length && !/[\s"\u201d)]/.test(text[i + 1]))) continue;
    const w = prevWord(text, i);
    if (text[i] === "." && w && (ABBREV.has(w.word.toLowerCase()) || /^\p{Lu}$/u.test(w.word))) continue;
    push(i + 1);
  }
  push(text.length);
  return segs;
}

const has = (seg, role) => seg.openers.some((c) => c.roles.includes(role));
const opensWith = (seg, role) => seg.openers.length && seg.openers[0].roles[0] === role;
const ASSUME = /^(?:\W*)(?:if|suppose|assuming|given that|se|si|caso|supposons|suponiendo|supondo)\b/iu;

// Roles by position. A unit is one argument: it starts at the first segment or at a segment opened by a
// continuation ("Praeterea", "Moreover"), and a conclusion closes it.
function readArgument(text, lang = null) {
  const L = guessLang(text, lang), segs = segment(text, L), units = [];
  let unit = null;
  for (const s of segs) {
    const isC = has(s, "conclusion") && !opensWith(s, "condition");
    if (!unit || (opensWith(s, "continuation") && !isC) || (unit.closed && !isC)) { unit = { segments: [], closed: false, opener: s.openers[0] || null }; units.push(unit); }
    s.role = isC ? "conclusion" : null;
    unit.segments.push(s);
    if (isC) unit.closed = true;
  }
  for (const u of units) labelUnit(u);
  return { lang: L, segments: segs.map(({ start, end, text: t, role, openers }) => ({ start, end, text: t, role, opener: openers[0] ? { form: openers[0].form, roles: openers[0].roles } : null })), units: units.map((u, i) => ({ segments: u.segments.map((s) => segs.indexOf(s)), movement: movement(u, units[i - 1]) })) };
}

function labelUnit(u) {
  const segs = u.segments, lastC = segs.map((s) => s.role === "conclusion").lastIndexOf(true);
  let sawMinor = false;
  segs.forEach((s, i) => {
    if (s.role) return;
    const minorish = has(s, "minor"), before = segs.slice(0, i).some((x) => !x.role || x.role === "premise" || x.role === "assumption");
    if (minorish && before && lastC > i) { s.role = sawMinor ? "supporting premise" : "minor premise"; sawMinor = true; }
    else if (has(s, "reversal") && !(lastC > i)) s.role = "turn";
    else if (ASSUME.test(s.text.replace(/^[\p{L}]+,\s*/u, (m) => (has(s, "continuation") ? "" : m)))) s.role = "assumption";
    else s.role = "premise";
  });
}

// How a unit moves against the one before: a list (opened by "Moreover", "Praeterea"), a turn (opened
// by "But", "However", "Sed contra", or holding a turn), a chain (its first premise takes up the
// previous conclusion's words) or a single argument.
function movement(u, prev) {
  const first = u.segments[0];
  if (u.segments.some((s) => s.role === "turn") || (first.openers[0] && first.openers[0].roles[0] === "reversal")) return "turn";
  if (first.openers[0] && first.openers[0].roles.includes("continuation") && prev) return "list";
  const prevC = prev && prev.segments.filter((s) => s.role === "conclusion").pop();
  if (prevC) { const a = new Set(content(prevC.text)); if (content(first.text).filter((w) => a.has(w)).length >= 2) return "chain"; }
  return "argument";
}

// The boundaries the lens draws: where each segment after the first starts.
const boundaries = (reading) => reading.segments.slice(1).map((s) => s.start);

return { findConnectives, guessLang, segment, readArgument, boundaries };
})();

// ---- claimtype.js
const M_claimtype = (() => {
// The claim-type marker (F7) and the inference-gap marker (F9), project-docs/ARGUMENT-LENS.md.
// F7 names what kind of claim each sentence makes, with the cue that decided it: a question, a
// quotation, a definition, a sourced statement, an opinion or value, an inference, or a factual claim
// with or without a source. F9 marks two moves: a claim about what another person knows, wants or
// intends (not observable from a post), and a conclusion whose words its premises do not contain.
// Every rule reads the move; none reads a side, a party or a person (tests/discourse.argument.test.js
// runs them with the sides swapped).
const { readArgument, segment, guessLang } = M_argument;
const { content } = M_text;

const CLAIM_DOES_NOT_PROVE = "A claim type is read from wording cues, so a sentence can carry two kinds, and irony or quotation can mislead the cue. It says what kind of claim the words make, not whether the claim is true.";
const GAP_DOES_NOT_PROVE = "An inference can be sound even when its words are new, and a claim about someone's intent can be right. The marker shows where the post goes beyond what it states; it does not say the conclusion is wrong.";

const SENT = /[^.!?\n]+[.!?]*/g;
const RULES = [
  ["question", /\?\s*$/u, "ends with a question mark"],
  ["quotation", /["“«][^"”»]{12,}["”»]/u, "a passage in quotation marks"],
  ["definition", /\b(?:by definition|is defined as|(?:the|its) (?:true |real )?meaning of|what counts as|means (?:that )?(?:a|an|the)\b|is not (?:a|an) (?:fact|concept|opinion|matter)\b|is (?:a|an) (?:philosophical|religious|political|legal) (?:concept|term)|in the (?:strict|literal) sense|o que se entende por|se define como|par définition)\b/iu, "defines or disputes what a word means"],
  ["sourced statement", /\b(?:according to|the (?:report|study|assessment|filing|ruling|record|transcript|data|census|survey)\s+(?:says|shows|found|concluded|states)|(?:historians|scientists|researchers|economists|intelligence|investigators|the court|the (?:un|who|odni|cia|fbi))\s+(?:say|says|found|concluded|agree|place|assessed|reported)|declassified|peer[- ]reviewed|published in|https?:\/\/)/iu, "names or links its source"],
  ["classification", /\b(?:is|was|are|were)\s+(?:not\s+)?(?:a\s+|an\s+)?(?:(?:far|hard|radical|extreme|literal|real|true)[- ]?)?(?:\w+\s+){0,3}?(?:\w+ists?|\w+isms?|extremists?|terrorists?|dictators?|tyrants?)\b/iu, "puts a person, group or idea in a category"],
  ["inference", /(?:^|\W)(?:therefore|thus|hence|so|which means|that means|this means|would mean|it follows|proves that|must have|clearly)\b/iu, "a conclusion connective"],
  ["opinion or value", /\b(?:i think|i believe|in my (?:view|opinion)|should|ought to|must|best|worst|greatest|terrible|disgusting|amazing|stupid|scary|evil|shameful|pathetic|beautiful|deserves?|everyone should)\b|!\s*$/iu, "evaluative or first-person wording"],
];
const FACT = /\b\p{Lu}\p{Ll}+\s+\w+ed\b|\b(?:\d{4}|\d+(?:[.,]\d+)?\s*(?:%|percent|million|billion|thousand)|(?:was|were|is|are|has|have|had|did)\s+\w+ed\b|(?:killed|hired|sent|signed|voted|said|wrote|published|arrested|paid|launched|invented|founded|died|won|lost|built|funded|ordered)\b)/iu;
const LINK = /https?:\/\/|\b\w+\.(?:com|org|gov|edu|net)\/\S+/iu;

// Words too general to count as fresh in a conclusion.
const PLAIN = new Set(["claim", "mean", "would", "could", "thing", "fact", "point", "case", "make", "made"]);

// One sentence's type: { type, cue }.
function claimTypeOf(sentence) {
  const s = sentence.trim();
  for (const [type, re, cue] of RULES) if (re.test(s)) return { type, cue };
  if (FACT.test(s)) return LINK.test(s) ? { type: "factual claim with a link", cue: "a statement of fact with a link" } : { type: "factual claim, no source", cue: "a statement of fact with no source given" };
  return { type: "statement", cue: "no cue for a narrower type" };
}

// Every sentence of a post, typed.
function claimTypes(text) {
  const t = String(text || "");
  return segment(t, guessLang(t)).flatMap((s) => s.text.split(/\n+/)).map((x) => x.trim()).filter((x) => x.length > 3).map((x) => ({ text: x, ...claimTypeOf(x) }));
}

// Claims about a third party's mind: knowing, wanting, intending, fearing, lying on purpose.
const MIND = /\b(?:he|she|they|his|her|their|[A-Z][a-z]+|(?:[Tt]he|[Tt]his|[Tt]hat)(?:\s+[a-z]+){1,2})\s+(?:absolutely |clearly |obviously |secretly )?(?:knows|knew|is aware|was aware|wants|wanted|intends|intended|is afraid|was afraid|fears|plans|planned|meant to|pretends|is pretending)\b|\b(?:a |the )?(?:calculated|deliberate|intentional) (?:lie|deception|move)\b|\bon purpose\b|\bit'?s (?:all )?about the (?:[Mm]oney|[Bb]enjamins)\b|\b(?:his|her|their) (?:real|true) (?:motive|reason|goal|agenda)\b/u;

// F9: { kind, text, why } for each gap in a post.
function inferenceGaps(text, lang = null) {
  const out = [], t = String(text || "");
  for (const s of t.match(SENT) || []) {
    const m = s.match(MIND);
    if (m) out.push({ kind: "mind", text: s.trim(), cue: m[0], why: "It states what someone else knows, wants or intends, which a post cannot show." });
  }
  const r = readArgument(t, lang);
  const premises = r.segments.filter((s) => s.role !== "conclusion"), have = new Set(premises.flatMap((s) => content(s.text)));
  for (const c of r.segments.filter((s) => s.role === "conclusion")) {
    if (!premises.length) continue;
    const words = [...new Set(content(c.text))].filter((w) => w.length > 3 && !PLAIN.has(w)), fresh = words.filter((w) => !have.has(w));
    if (words.length >= 4 && fresh.length / words.length >= 0.6) out.push({ kind: "leap", text: c.text, cue: c.opener ? c.opener.form : "", fresh: fresh.slice(0, 8), why: `The conclusion brings ${fresh.length} of its ${words.length} meaning words in fresh: ${fresh.slice(0, 5).join(", ")}. The premises before it do not contain them.` });
  }
  return out;
}

return { CLAIM_DOES_NOT_PROVE, GAP_DOES_NOT_PROVE, claimTypeOf, claimTypes, inferenceGaps };
})();

// ---- isomer.js
const M_isomer = (() => {
// The reframing marker (project-docs/ARGUMENT-LENS.md): an isomer is the same parts in a different
// arrangement. A post names the same people and things as the sources beneath it (the replies that bring
// a source, the documents they link) but puts them in an act none of those sources states, or states
// only to deny. The worked example of 2026-10-26: a documented relationship and a documented killing,
// rearranged as "hired a hitman". The marker compares words; it reads no side and no person.
const { keyTerms, findIn } = M_docclaim;
const { content, fold } = M_text;

const ISOMER_DOES_NOT_PROVE = "Sources can be incomplete, and words the sources lack can still be true. This shows only that the post's arrangement goes past what the sources beneath it say.";
const NEGATION = /\b(?:no|not|never|nor|false|untrue|without|denied|denies|deny|no credible evidence|there is no|unfounded|baseless)\b/i;

// Where a term sits in a source: "stated", "denied" (a negation in the 80 characters before it), or null.
function standing(source, term) {
  const t = fold(source), hit = findIn(source, term);
  if (!hit) return null;
  const at = t.indexOf(hit);
  return at >= 0 && NEGATION.test(t.slice(Math.max(0, at - 80), at)) ? "denied" : "stated";
}

// claim: the post's text; sources: [{ text }]. Returns null, or { shared, added, denied, sources }.
function reframing(claim, sources) {
  const usable = (sources || []).filter((s) => s && s.text && s.text.length > 40);
  if (!usable.length) return null;
  const names = keyTerms(claim).filter((t) => t.kind === "name").map((t) => t.term);
  const nameWords = new Set(names.flatMap((n) => content(n)));
  const shared = names.filter((n) => usable.some((s) => standing(s.text, n)));
  const acts = [...new Set(content(claim).filter((w) => w.length >= 4 && !nameWords.has(w)))];
  const added = [], denied = [];
  for (const w of acts) {
    const st = usable.map((s) => standing(s.text, w));
    if (st.includes("stated")) continue;
    (st.includes("denied") ? denied : added).push(w);
  }
  if (shared.length < 2 || added.length + denied.length < 1) return null;
  return { shared, added, denied, sources: usable.length };
}

function reframingRows(r) {
  return [
    ["Same parts", `The post names what the ${r.sources} ${r.sources === 1 ? "source" : "sources"} beneath it name: ${r.shared.join(", ")}.`],
    ...(r.denied.length ? [["Stated only to deny", `The sources contain ${r.denied.map((w) => `"${w}"`).join(", ")} only next to a denial.`]] : []),
    ...(r.added.length ? [["In none of the sources", r.added.slice(0, 10).map((w) => `"${w}"`).join(", ")]] : []),
    ["What it shows", ISOMER_DOES_NOT_PROVE],
  ];
}

return { ISOMER_DOES_NOT_PROVE, reframing, reframingRows };
})();

globalThis.PBD = Object.freeze({ ...M_text, ...M_quotes, ...M_persona, ...M_stats, ...M_docclaim, ...M_corrections, ...M_argument_measured, ...M_cards, ...M_sheets, ...M_parts, ...M_argument_cues, ...M_argument, ...M_claimtype, ...M_isomer });
})();
